-- Copy review: new synopses for the titles, applied to rows that already exist (the seeds carry the same text).

update public.avengers_titles set synopsis_pt = $s$Em 1942, o franzino Steve Rogers se torna o supersoldado Capitão América e enfrenta o Caveira Vermelha e a HIDRA durante a Segunda Guerra Mundial.$s$ where slug = 'captain-america-the-first-avenger';
update public.avengers_titles set synopsis_pt = $s$Nos anos 1990, a piloto Carol Danvers descobre seu passado em meio à guerra entre Kree e Skrulls e se torna uma das heroínas mais poderosas do universo.$s$ where slug = 'captain-marvel';
update public.avengers_titles set synopsis_pt = $s$Sequestrado no Afeganistão, o bilionário Tony Stark constrói uma armadura para escapar. A experiência muda sua vida e o leva a usar a tecnologia para proteger o mundo.$s$ where slug = 'iron-man';
update public.avengers_titles set synopsis_pt = $s$Com sua identidade revelada, Tony enfrenta o governo, o rival Justin Hammer e o vingativo Ivan Vanko — enquanto o reator em seu peito ameaça sua vida.$s$ where slug = 'iron-man-2';
update public.avengers_titles set synopsis_pt = $s$Enquanto foge do exército, Bruce Banner procura uma cura para a criatura dentro de si. Mas o soldado Emil Blonsky também se transforma — no Abominável.$s$ where slug = 'the-incredible-hulk';
update public.avengers_titles set synopsis_pt = $s$Banido de Asgard por sua arrogância, o deus do trovão chega à Terra sem poderes e precisa provar que é digno de empunhar o martelo Mjölnir.$s$ where slug = 'thor';
update public.avengers_titles set synopsis_pt = $s$Nick Fury reúne Homem de Ferro, Capitão América, Thor, Hulk, Viúva Negra e Gavião Arqueiro para deter Loki e impedir uma invasão alienígena em Nova York.$s$ where slug = 'the-avengers';
update public.avengers_titles set synopsis_pt = $s$Thor enfrenta Malekith e os Elfos Negros, que querem usar o poder do Éter para mergulhar os Nove Reinos na escuridão.$s$ where slug = 'thor-the-dark-world';
update public.avengers_titles set synopsis_pt = $s$Ainda abalado pelos acontecimentos em Nova York, Tony Stark enfrenta o terrorista Mandarim e precisa descobrir quem é sem depender da armadura.$s$ where slug = 'iron-man-3';
update public.avengers_titles set synopsis_pt = $s$Steve Rogers descobre uma conspiração dentro da S.H.I.E.L.D. e precisa enfrentar um misterioso assassino ligado ao seu passado: o Soldado Invernal.$s$ where slug = 'captain-america-the-winter-soldier';
update public.avengers_titles set synopsis_pt = $s$O ladrão Peter Quill rouba uma esfera disputada por forças poderosas e acaba formando uma equipe improvável com Gamora, Drax, Rocket e Groot.$s$ where slug = 'guardians-of-the-galaxy';
update public.avengers_titles set synopsis_pt = $s$Os Guardiões conhecem Ego, o pai de Peter Quill, e descobrem que os laços de família vão muito além do sangue.$s$ where slug = 'guardians-of-the-galaxy-vol-2';
update public.avengers_titles set synopsis_pt = $s$Tony Stark cria uma inteligência artificial para proteger a Terra, mas Ultron chega à conclusão de que só haverá paz quando a humanidade deixar de existir.$s$ where slug = 'avengers-age-of-ultron';
update public.avengers_titles set synopsis_pt = $s$O ex-presidiário Scott Lang veste o traje criado por Hank Pym, capaz de encolhê-lo e ampliar sua força, para impedir que a tecnologia caia em mãos erradas.$s$ where slug = 'ant-man';
update public.avengers_titles set synopsis_pt = $s$Um acordo para regulamentar a atuação dos heróis divide os Vingadores: Capitão América e Homem de Ferro ficam em lados opostos.$s$ where slug = 'captain-america-civil-war';
update public.avengers_titles set synopsis_pt = $s$Foragida após os acontecimentos de Guerra Civil, Natasha Romanoff enfrenta o passado na Sala Vermelha e reencontra a família que deixou para trás.$s$ where slug = 'black-widow';
update public.avengers_titles set synopsis_pt = $s$T’Challa assume o trono de Wakanda, mas precisa enfrentar Killmonger, um rival com fortes ligações com o passado do reino.$s$ where slug = 'black-panther';
update public.avengers_titles set synopsis_pt = $s$Depois dos acontecimentos de Guerra Civil, Peter Parker tenta conciliar a escola com a vida de herói enquanto enfrenta o Abutre, com Tony Stark de olho.$s$ where slug = 'spider-man-homecoming';
update public.avengers_titles set synopsis_pt = $s$Depois que um acidente compromete suas mãos, o cirurgião Stephen Strange viaja ao Nepal em busca de uma cura e acaba descobrindo as artes místicas.$s$ where slug = 'doctor-strange';
update public.avengers_titles set synopsis_pt = $s$Preso em Sakaar e sem seu martelo, Thor precisa enfrentar Hulk numa arena e voltar a tempo de salvar Asgard de Hela.$s$ where slug = 'thor-ragnarok';
update public.avengers_titles set synopsis_pt = $s$Em prisão domiciliar, Scott Lang se une a Hope e Hank Pym em uma missão para resgatar Janet van Dyne do Reino Quântico.$s$ where slug = 'ant-man-and-the-wasp';
update public.avengers_titles set synopsis_pt = $s$Thanos parte em busca das seis Joias do Infinito. Vingadores e Guardiões da Galáxia precisam se unir para impedir que ele elimine metade da vida do universo.$s$ where slug = 'avengers-infinity-war';
update public.avengers_titles set synopsis_pt = $s$Cinco anos após o estalo de Thanos, os Vingadores restantes arriscam tudo em uma última missão para tentar reverter a tragédia.$s$ where slug = 'avengers-endgame';
update public.avengers_titles set synopsis_pt = $s$Shang-Chi tenta deixar o passado para trás, mas é forçado a encarar a organização dos Dez Anéis, liderada por seu próprio pai.$s$ where slug = 'shang-chi-and-the-legend-of-the-ten-rings';
update public.avengers_titles set synopsis_pt = $s$Após viverem escondidos na Terra por milênios, seres imortais se reúnem para enfrentar os Deviantes e descobrir a verdade por trás de sua missão.$s$ where slug = 'eternals';
update public.avengers_titles set synopsis_pt = $s$Durante uma viagem escolar pela Europa, Peter Parker enfrenta ameaças elementais ao lado de Mysterio, um herói que afirma vir de outra dimensão.$s$ where slug = 'spider-man-far-from-home';
update public.avengers_titles set synopsis_pt = $s$Com sua identidade revelada, Peter pede ajuda ao Doutor Estranho. Mas um feitiço dá errado e abre as portas do multiverso.$s$ where slug = 'spider-man-no-way-home';
update public.avengers_titles set synopsis_pt = $s$Doutor Estranho protege America Chavez, uma jovem capaz de viajar entre universos, e enfrenta uma ameaça inesperada: a Feiticeira Escarlate.$s$ where slug = 'doctor-strange-in-the-multiverse-of-madness';
update public.avengers_titles set synopsis_pt = $s$Thor deixa a aposentadoria para enfrentar Gorr, o Carniceiro dos Deuses, e reencontra Jane Foster — agora empunhando o Mjölnir.$s$ where slug = 'thor-love-and-thunder';
update public.avengers_titles set synopsis_pt = $s$Após a morte do rei T’Challa, Wakanda precisa proteger seu povo diante da ameaça de Namor e da nação submarina de Talokan.$s$ where slug = 'black-panther-wakanda-forever';
update public.avengers_titles set synopsis_pt = $s$Scott Lang e sua família são arrastados para o Reino Quântico, onde encontram Kang, o Conquistador.$s$ where slug = 'ant-man-and-the-wasp-quantumania';
update public.avengers_titles set synopsis_pt = $s$Para salvar Rocket, os Guardiões enfrentam o Alto Evolucionário, o cientista responsável por sua criação e por seu sofrimento.$s$ where slug = 'guardians-of-the-galaxy-vol-3';
update public.avengers_titles set synopsis_pt = $s$Sempre que usam seus poderes, Carol Danvers, Monica Rambeau e Kamala Khan trocam de lugar. Para entender o que está acontecendo, elas precisam aprender a trabalhar juntas.$s$ where slug = 'the-marvels';
update public.avengers_titles set synopsis_pt = $s$A TVA recruta Deadpool para uma missão que pode salvar seu universo. Para isso, ele precisa encontrar um Wolverine — e acaba no Vazio.$s$ where slug = 'deadpool-wolverine';
update public.avengers_titles set synopsis_pt = $s$Sam Wilson, o novo Capitão América, se vê no centro de um incidente internacional envolvendo o presidente Thaddeus Ross.$s$ where slug = 'captain-america-brave-new-world';
update public.avengers_titles set synopsis_pt = $s$Yelena Belova e um grupo de anti-heróis caem em uma armadilha e precisam trabalhar juntos para sobreviver a uma missão que pode mudar suas vidas.$s$ where slug = 'thunderbolts';
update public.avengers_titles set synopsis_pt = $s$Em uma Terra retrofuturista dos anos 1960, o Quarteto Fantástico enfrenta Galactus e sua arauta, a Surfista Prateada.$s$ where slug = 'the-fantastic-four-first-steps';
update public.avengers_titles set synopsis_pt = $s$Peter Parker tenta recomeçar a vida em Nova York, onde ninguém se lembra de quem ele é. Mesmo assim, o Homem-Aranha continua protegendo a cidade.$s$ where slug = 'spider-man-brand-new-day';
update public.avengers_titles set synopsis_pt = $s$Wanda e Visão vivem uma vida perfeita, como em uma sitcom nos subúrbios, até que a realidade começa a sair dos trilhos. A série prepara o terreno para Doutor Estranho no Multiverso da Loucura.$s$ where slug = 'wandavision';
update public.avengers_titles set synopsis_pt = $s$Sam Wilson e Bucky Barnes tentam entender o legado do Capitão América e o que fazer com ele. A série mostra como Sam assume o manto em Capitão América: Admirável Mundo Novo.$s$ where slug = 'falcon-and-the-winter-soldier';
update public.avengers_titles set synopsis_pt = $s$Capturado pela Autoridade de Variância Temporal, Loki descobre a existência da Linha do Tempo Sagrada — e sinais de que o multiverso está por vir.$s$ where slug = 'loki';
update public.avengers_titles set synopsis_pt = $s$Uma animação que explora o que aconteceria se momentos decisivos do MCU tivessem seguido outros caminhos. Uma viagem por realidades alternativas.$s$ where slug = 'what-if';
update public.avengers_titles set synopsis_pt = $s$Continuação da animação clássica dos anos 1990: sem Charles Xavier, os mutantes enfrentam o preconceito do mundo que juraram proteger.$s$ where slug = 'x-men-97';
update public.avengers_titles set synopsis_pt = $s$Temidos pelo mundo, os mutantes encontram abrigo na escola de Charles Xavier. Enquanto isso, Magneto prepara um plano contra a humanidade.$s$ where slug = 'x-men';
update public.avengers_titles set synopsis_pt = $s$Após um atentado contra o presidente, um coronel declara guerra aos mutantes. Para enfrentá-lo, os X-Men e a Irmandade precisam se unir.$s$ where slug = 'x2';
update public.avengers_titles set synopsis_pt = $s$Nos anos 1960, Charles Xavier e Erik Lehnsherr se unem para formar uma equipe de mutantes — até que suas diferenças os colocam em lados opostos.$s$ where slug = 'x-men-first-class';
update public.avengers_titles set synopsis_pt = $s$Wolverine viaja ao passado para impedir um futuro em que os mutantes são caçados e estão à beira da extinção.$s$ where slug = 'x-men-days-of-future-past';
update public.avengers_titles set synopsis_pt = $s$Após um experimento que o deixa com poderes de cura e uma aparência transformada, Wade Wilson assume a identidade do mercenário tagarela Deadpool.$s$ where slug = 'deadpool';
update public.avengers_titles set synopsis_pt = $s$Em um futuro em que os mutantes quase desapareceram, um Wolverine cansado cuida de um Professor X doente e protege uma menina com poderes semelhantes aos seus.$s$ where slug = 'logan';
update public.avengers_titles set synopsis_pt = $s$Deadpool reúne a X-Force para proteger um jovem mutante do implacável Cable.$s$ where slug = 'deadpool-2';
